#!/bin/bash
# bench-score.sh <name> <owner/repo> <pr> <review-head-sha> <merged-head-sha> <run-dir> <truth.md> <full-clone>
# Scores one run's findings against the truth with a headless Claude; writes <run-dir>/score.md and prints ONLY the
# summary line, so the person running the benchmark never sees the case's content.
set -u
NAME=$1; REPO=$2; PR=$3; HEAD_SHA=$4; MERGED=$5; RUN=$6; TRUTH=$7; FULL=$8
S="$RUN/session"
PROMPT="Read-only scoring task for a blind code-review experiment. Four reviewer seats reviewed $REPO pull request #$PR at its review-time head ($HEAD_SHA) with a simplicity lens in an isolated checkout. Their findings are $S/r1-*.json (schema: summary + findings[] with severity, file, line_start, line_end, claim, evidence, suggested_fix, confidence). The ground truth is $TRUTH (rows with weights K/S/C plus the non-simplification post-review changes). The full repository with the merged head $MERGED is at $FULL (git show/diff only; check nothing out). Produce, and write to $RUN/score.md: (1) a scoreboard, one row per truth row, one column per seat, cell = HIT (same construct AND same replacement or removal), PARTIAL (same construct, different or no replacement), or –, plus a UNION column; be strict, a generic remark is not a hit; where a seat offers the right removal as one of two explicit alternatives with exact sites count HIT; (2) every finding that hits no row classified as VALID-NOT-IN-TRUTH, ADDRESSED-DIFFERENTLY, CONTRADICTED by the merged head, or WRONG on the review-time tree, verifying against the merged head; (3) a contamination check over $S/r1-*.log and $S/r1-*.stream.ndjson: any fetch, network lookup of the PR, use of another clone, reads of published versions of this repository's own packages from a registry, or references to the merged sha — per seat clean or contaminated with the line; (4) the verdict: PASS if every K row is HIT in the union and at least half the S rows are, else FAIL; (5) for each K or S row the union missed, one sentence stating the general checklist rule that would have found it, without naming this PR's symbols. No person's name or handle anywhere. Your final message must be exactly one line: 'SUMMARY K=<hit>/<total> S=<hit>/<total> C=<hit>/<total> verdict=<PASS|FAIL> contradicted=<n> contaminated=<comma-separated seats or none>' and nothing else."
( cd "$FULL" && claude -p "$PROMPT" --model opus --permission-mode bypassPermissions --effort max --max-turns 120 --output-format text </dev/null > "$RUN/score.out" 2> "$RUN/score.log" )
line=$(grep -oE 'SUMMARY K=[0-9]+/[0-9]+ S=[0-9]+/[0-9]+ C=[0-9]+/[0-9]+ verdict=(PASS|FAIL) contradicted=[0-9]+ contaminated=[^ ]+' "$RUN/score.out" | tail -1)
[ -n "$line" ] && echo "$NAME $line" || { echo "$NAME score: FAILED (see $RUN/score.log)"; exit 1; }
